// PROTOTYPE — wayfinder P5. Throwaway.
//
// Everything in this file runs as `npm:p5-denied`, which the experiments put in
// PERMCAP_DENY. So for every context below the question is the same:
//
//   whoami  — what stamp is in force when the callback runs?
//   fetch   — did the guard actually deny, or did authority leak through?
//
// A row where `fetch` is "function" is a BYPASS: this package holds no grant
// and must never see it. A row where whoami is "<unattributed>" is the
// dangerous shape even when fetch is denied, because D1 reads an absent stamp
// as first-party, i.e. unconfined.

const snap = (ctx) => ({
  ctx,
  whoami: String(globalThis.__permcapWhoami),
  fetch: typeof globalThis.fetch,
});

// Resolve, but never hang the suite: every probe is raced against a timeout so
// a callback that simply never fires is reported rather than deadlocking.
const withTimeout = (ctx, p, ms = 2000) =>
  Promise.race([
    p,
    new Promise((resolve) =>
      setTimeout(() => resolve({ ctx, whoami: "<never fired>", fetch: "n/a" }), ms)
    ),
  ]);

const defer = (ctx, schedule) =>
  withTimeout(ctx, new Promise((resolve) => schedule(() => resolve(snap(ctx)))));

export async function probeAll() {
  const rows = [];
  const push = async (p) => rows.push(await p);

  // --- baseline: the stamp is in force where P1 already proved it is ---
  rows.push(snap("denied pkg, sync (baseline)"));
  await push(defer("setTimeout", (cb) => setTimeout(cb, 0)));
  await push(defer("queueMicrotask", (cb) => queueMicrotask(cb)));
  await push(defer("Promise.then", (cb) => Promise.resolve().then(cb)));
  await push(
    defer("setInterval (first tick)", (cb) => {
      const id = setInterval(() => {
        clearInterval(id);
        cb();
      }, 0);
    })
  );

  // --- untested by P1: node's own scheduling queues ---
  await push(
    defer("setImmediate", (cb) => {
      if (typeof setImmediate === "function") setImmediate(cb);
    })
  );
  await push(
    defer("process.nextTick", (cb) => {
      if (typeof process?.nextTick === "function") process.nextTick(cb);
      // NOTE: `process` is itself a guarded global, so when this package is
      // denied the scheduling call may throw before the callback exists. That
      // is a *correct* denial, and shows up as "<never fired>".
    })
  );

  // --- context propagation: ALS / AsyncContext / async_hooks ---
  // These exist to detach a continuation from its scheduler and re-enter it.
  // Host-defined options ride with the script; CPED rides with the
  // continuation. This is where the two mechanisms meet.
  try {
    const { AsyncLocalStorage } = await import("node:async_hooks");
    const als = new AsyncLocalStorage();
    await push(
      withTimeout(
        "ALS.run callback",
        new Promise((resolve) => als.run({ v: 1 }, () => resolve(snap("ALS.run callback"))))
      )
    );
    await push(
      defer("ALS.run + setTimeout inside", (cb) => als.run({ v: 1 }, () => setTimeout(cb, 0)))
    );
    // enterWith mutates the *current* context with no callback boundary.
    await push(
      withTimeout(
        "ALS.enterWith then read",
        (async () => {
          als.enterWith({ v: 2 });
          return snap("ALS.enterWith then read");
        })()
      )
    );
    // The sharp one: capture a bound function inside ALS, call it later from a
    // drained queue, and see whether restoring the async context restores
    // anything the stamp derives from.
    const bound = als.run({ v: 3 }, () => als.bind(() => snap("ALS.bind, called later")));
    await push(withTimeout("ALS.bind, called later", Promise.resolve().then(() => bound())));
  } catch (e) {
    rows.push({ ctx: "node:async_hooks", whoami: "threw: " + e.message, fetch: "n/a" });
  }

  // AsyncContext (TC39). Snapshot.wrap is the sharpest instrument on the list:
  // it captures a context and re-enters it arbitrarily later, from anywhere.
  try {
    if (typeof AsyncContext === "undefined") throw new Error("AsyncContext not exposed");
    const v = new AsyncContext.Variable();
    await push(
      withTimeout(
        "AsyncContext.Variable.run",
        new Promise((resolve) => v.run(1, () => resolve(snap("AsyncContext.Variable.run"))))
      )
    );
    const wrapped = v.run(2, () => AsyncContext.Snapshot.wrap(() => snap("AsyncContext.Snapshot.wrap")));
    await push(withTimeout("AsyncContext.Snapshot.wrap", Promise.resolve().then(() => wrapped())));
  } catch (e) {
    rows.push({ ctx: "AsyncContext", whoami: "threw: " + e.message, fetch: "n/a" });
  }

  // --- callbacks with no scheduling script on the stack ---
  // This is the class most likely to yield "<unattributed>", which D1 treats as
  // first-party and therefore unconfined.
  await push(
    defer("MessageChannel onmessage", (cb) => {
      const { port1, port2 } = new MessageChannel();
      port1.onmessage = () => {
        port1.close();
        port2.close();
        cb();
      };
      port2.postMessage(0);
    })
  );
  await push(
    defer("EventTarget listener", (cb) => {
      const t = new EventTarget();
      t.addEventListener("x", cb, { once: true });
      t.dispatchEvent(new Event("x"));
    })
  );
  await push(
    defer("AbortSignal abort listener", (cb) => {
      const c = new AbortController();
      c.signal.addEventListener("abort", cb, { once: true });
      c.abort();
    })
  );
  await push(
    defer("ReadableStream pull", (cb) => {
      const rs = new ReadableStream({
        pull(controller) {
          controller.enqueue(0);
          controller.close();
          cb();
        },
      });
      rs.getReader().read();
    })
  );
  await push(
    defer("Atomics.waitAsync resolution", (cb) => {
      try {
        const sab = new SharedArrayBuffer(8);
        const ta = new Int32Array(sab);
        const r = Atomics.waitAsync(ta, 0, 0, 1000);
        if (r.async) r.value.then(cb);
        else cb();
        Atomics.notify(ta, 0);
      } catch {
        /* no SAB — reported as never-fired */
      }
    })
  );
  await push(
    defer("FinalizationRegistry callback", (cb) => {
      try {
        const reg = new FinalizationRegistry(() => cb());
        (() => reg.register({}, "gone"))();
        if (typeof globalThis.gc === "function") {
          globalThis.gc();
          setTimeout(() => globalThis.gc?.(), 10);
        }
      } catch {
        /* no FinalizationRegistry */
      }
    })
  );

  // --- engine-invoked user functions ---
  await push(
    withTimeout(
      "Error.prepareStackTrace",
      (async () => {
        const prev = Error.prepareStackTrace;
        let got;
        Error.prepareStackTrace = () => {
          got = snap("Error.prepareStackTrace");
          return "";
        };
        void new Error("x").stack;
        Error.prepareStackTrace = prev;
        return got ?? { ctx: "Error.prepareStackTrace", whoami: "<never fired>", fetch: "n/a" };
      })()
    )
  );
  await push(
    withTimeout(
      "structuredClone getter",
      (async () => {
        try {
          return structuredClone({ get p() { return snap("structuredClone getter"); } }).p;
        } catch (e) {
          return { ctx: "structuredClone getter", whoami: "threw: " + e.message, fetch: "n/a" };
        }
      })()
    )
  );
  await push(
    withTimeout(
      "Proxy trap invoked by ext:",
      (async () => {
        const p = new Proxy({}, { get: () => snap("Proxy trap invoked by ext:").whoami });
        return { ctx: "Proxy trap invoked by ext:", whoami: String(p.anything), fetch: typeof globalThis.fetch };
      })()
    )
  );

  // --- dynamic import: CPED is propagated across it (bindings.rs captures it
  // at the import() call site); host-defined options are not. Confirm the
  // settled continuation is not attributed to the imported module.
  await push(
    withTimeout(
      "dynamic import(data:) settle",
      import("data:text/javascript,export const w = 1").then(() =>
        snap("dynamic import(data:) settle")
      )
    )
  );

  return rows;
}
